import pandas as pd

def count_rows_in_csv(filename):
    df = pd.read_csv(filename)
    return len(df)

import numpy as np

def calculate_mean_axis0(arr):
    return np.mean(arr, axis=0)

import requests

def fetch_json_data(url):
    response = requests.get(url)
    response.raise_for_status()
    return response.json()
